add_action( 'init', 'perfectpixel_move_gallery_setup' );

function perfectpixel_move_gallery_setup() {
	remove_action( 'woocommerce_product_thumbnails', 'woocommerce_show_product_thumbnails', 20 );
	add_action( 'woocommerce_single_product_summary', 'perfectpixel_moved_gallery_output', 25 );
}

function perfectpixel_moved_gallery_output() {
	global $product;
	if ( ! $product || ! $product->get_gallery_image_ids() ) {
		return;
	}
	$columns = max( 1, (int) '{{moved_gallery_columns}}' );
	echo '<div class="perfectpixel-moved-gallery" style="display:grid;grid-template-columns:repeat(' . (int) $columns . ',1fr);gap:.5em;margin-bottom:1.5em">';
	foreach ( $product->get_gallery_image_ids() as $image_id ) {
		printf(
			'<a href="%s" target="_blank" rel="noopener">%s</a>',
			esc_url( wp_get_attachment_image_url( $image_id, 'full' ) ),
			wp_get_attachment_image( $image_id, 'woocommerce_thumbnail' )
		);
	}
	echo '</div>';
}
